// QL-WIRE + QL-13 (game side of the 21 Ch1-2 errands, content/quests/ch12): everything main.js needs that is not in the quest book itself.
//  - gateOnMeet: errands only open after the first talk with Burl at home (else they pre-empt his `bear.home` greeting).
//  - (QL-T4) errand dialogue routes are generated by questSnippets.js (all givers with a dialogue, Burl and Rook included).
//  - isWorn: book.packOps.equipped(id) from components.equipment.
//  - createErrands: inspect hook for object givers (post / notePost; relays via their relay.wake touch), talk.<site> flags,
//    target1..3.hit (sword + arrow both emit combat:hit {target}), escort.bear.relayBend.
//  - mainSync (Rook's main quests): book status <-> the `s.mq.<id>.{available,active,ready,done}` flags his dialogue reads; `.accept` / `.handin` flags -> book.accept / handIn.
// No render / engine code; pure functions + a small stateful object, tested in errands.test.js.

const BURL_ENTITY = 'bear';
/** Quest-site name for an entity id (flag `talk.<site>`): Burl's entity is `bear`, every other site is its entity id. */
const CHART_PIECES = ['chart.river', 'chart.westFells']; // MAP-28 / Ch3: chart-piece items -> world flag chart.<area> (review 12d: module const)
export const siteOf = (entityId) => (entityId === BURL_ENTITY ? 'burl' : entityId);

/** OB-187 (D-105/D-106): an offer '!' needs its prerequisites. A side quest that only waits on the boar hand-in (e.g. sq.wreck.plate at the gondola)
 *  showed a blue '!' while the opening chain (follow Burl, wake the waystone) was still running. Such defs now also require burl.stone done.
 *  The Burl chain quests ('burl.*') and defs that already name a later chain quest are untouched. Returns d or a copy. */
function gateOnStone(d, hasStone) {
  if (!hasStone || !d || typeof d.id !== 'string' || d.id.startsWith('burl.') || !Array.isArray(d.requires)) return d;
  const q = (id) => d.requires.some((r) => r && r.quest === id);
  if (!q('burl.boars') || q('burl.stone') || q('burl.follow')) return d;
  return { ...d, requires: [...d.requires, { quest: 'burl.stone', done: true }] };
}

/** Returns defs where every {flag:'burl.home'} requirement - and every Burl-given errand (sq.*, giver.npc 'bear', e.g. sq.honey / sq.burl.fire, which
 *  open after Rook's quests and have no burl.home flag) - is joined by {flag:'burl.home.met'}, so no errand offer pre-empts his `bear.home` greeting
 *  (BURL-HOME-01). Defs may be frozen: copies, input untouched. */
export function gateOnMeet(defs) {
  const hasStone = defs.some((d) => d && d.id === 'burl.stone');
  return defs.map((d) => {
    d = gateOnStone(d, hasStone);
    const burlErrand = typeof d.id === 'string' && d.id.startsWith('sq.') && d.giver && d.giver.npc === BURL_ENTITY;
    const req = Array.isArray(d.requires) ? d.requires : (burlErrand ? [] : null);
    if (!req || !(burlErrand || req.some((r) => r && r.flag === 'burl.home')) || req.some((r) => r && r.flag === 'burl.home.met')) return d;
    return { ...d, requires: [...req, { flag: 'burl.home.met' }] };
  });
}

/** True when item `id` is worn in any slot of components.equipment `eq` (slot value = item id, or {id}). */
export function isWorn(eq, id) {
  if (!eq) return false;
  for (const k of Object.keys(eq)) { const v = eq[k]; if (v === id || (v && typeof v === 'object' && v.id === id)) return true; }
  return false;
}

/** OB-054b: short plain noun for an interactable's prompt. Table first (ids whose camelCase split reads badly), else the id split into words. */
// OB-094: a giver whose site entity is an invisible marker picks on the VISIBLE prop's collider shapes instead (the marker 'gondola'
// sits at the tower centre with no model; the wreck you see is the tower level prop 'tower.gondola')
const PICK_PROP = { gondola: 'tower.gondola' };
import { NPC_NAMES, OBJECT_LABELS } from './npcNames.js'; // R6-FIX A: names live in ONE module
const { bear: _b, rook: _r, hesk: _h, dorrin: _d, ...ERRAND_NPC_NAMES } = NPC_NAMES; // these four never had an errand label: keep the player text identical
const LABELS = { ...OBJECT_LABELS, ...ERRAND_NPC_NAMES };
export function labelOf(id) { return LABELS[id] || String(id).replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase(); }
/** '[E] <Verb> <name>' capped at 28 chars (name trimmed, never a bare verb). */
export function promptFor(verb, name) { return ('[E] ' + verb + ' ' + name).slice(0, 28).trim(); }

/** Banner rows for an object inspect result: the writer's lines for the action, else null (caller keeps def.giver text). */
export function bannerLines(def, action, wrap, maxRows = 10) {
  const L = def && def.lines; if (!L) return null;
  const set = action === 'accept' ? L.offer : action === 'handin' ? (L.ready || L.done ? [...(L.ready || []), ...(L.done || [])] : null) : action === 'refuse' ? L.active : null;
  if (!Array.isArray(set) || !set.length) return null;
  const rows = []; for (const l of set) for (const r of wrap(l)) rows.push(r);
  return rows.slice(0, maxRows);
}

const ESCORT_R = 14;
const MQ = ['mq.bend.call', 'mq.river.road', 'mq.ford.stones', 'mq.ford.mirror', 'mq.smoke', 'mq.ow.path', 'mq.ow.fence', 'mq.ow.names', 'mq.ow.relay', 'mq.ow.board']; // + Ch3 (Hesk / Dorrin): names + relay run through the dialogue flags // Rook's main quests (world.state keys 'mq.<id>.*' = dialogue 's.mq.<id>.*')
const PULSE_DELAY = 4; // seconds after the Bend relay wakes (questline: flag relay.bend.pulseSeen)
const ACTIVE = 2; // questBook statusOf: 0 unavailable, 1 available, 2 active, 3 ready, 4 done
/**
 * @param {{getBook:()=>any, questFlag:(k:string,v?:any)=>any, inspect:(id:string)=>void}} o
 *   inspect(objectId) = main's QL-04 sink (book.inspect + banner). questFlag = world.state + book.feed.
 */
export function createErrands({ getBook, questFlag, inspect, note, texts }) {
  let world = null, relayEnt = new Map(), pulseT = -1;
  const T = (texts && texts.texts) || {}; // content/dialogue/inspect.json: look-at table (key -> {prompt, title, lines, ...})
  const textOf = new Map(); // entity id -> table key (built at load)
  const offered = new Set(); // OB-126: relay entity ids whose errand was shown (offer) this session
  const looked = new Set(); // second look at the same anchor shows the `again` variant
  let nestWaiting = [];     // anchors that appear only after their item was taken
  const status = (id) => { const b = getBook(); return b ? b.statusOf(id) : -1; };

  /** An ACTIVE quest has a flag objective `key`. */
  function wants(key) {
    const b = getBook(); if (!b) return false;
    for (let i = 1; i < b.count; i++) {
      if (b.status(i) !== ACTIVE) continue;
      for (const o of b.def(i).objectives) if (o.when && o.when.type === 'flag' && o.when.id === key) return true;
    }
    return false;
  }
  const api = {
    /**
     * Data-driven look-at anchors: every entity whose components.inspect.text is a key of the table, plus the table's own `entities`
     * (lamps, knot, gate, nest). `afterItem` anchors wait until that item was taken (mainSync adds them). Returns the number added.
     */
    loadTexts(w) {
      textOf.clear(); nestWaiting = []; let n = 0;
      const put = (id, key, d) => {
        if (!d || !d.transform || textOf.has(id)) return;
        textOf.set(id, key);
        const t = T[key];
        if (t.afterItem && !api.itemTaken(t.afterItem)) { nestWaiting.push(id); return; }
        n += api.addLook(w, id, d);
      };
      if (typeof w.forEachEntity === 'function') w.forEachEntity((e, id) => {
        const d = e && (e.data || e), c = d && d.components, k = c && c.inspect && c.inspect.text;
        if (k && T[k] && T[k].prompt) put(id, k, d);
      });
      for (const key of Object.keys(T)) for (const id of T[key].entities || []) { const h = w.get(id); if (T[key].prompt) put(id, key, h && h.data); }
      return n;
    },
    itemTaken(item) { const b = getBook(); return !!(b && b.packOps && (b.packOps.count(item) > 0 || b.statusOf('mq.ford.mirror') === 4)); },
    addLook(w, id, d) {
      const key = 'qi.' + id, t = T[textOf.get(id)];
      if (w.interactables.some((r) => r.key === key)) return 0;
      w.addInteractable({ key, name: 'quest.inspect', x: d.transform.x, y: d.transform.y, z: d.transform.z + 0.6, pick: (w.propPickBox && w.propPickBox(PICK_PROP[id] || id)) || undefined, pickShapes: (w.propPickShapes && w.propPickShapes(PICK_PROP[id] || id)) || undefined, radius: t.radius || 2.4, prompt: t.prompt, def: { objectId: id } });
      return 1;
    },
    /** world:loaded: [E] Inspect on the object givers that have no dialogue and no relay touch of their own. */
    load(w) {
      world = w; relayEnt = new Map(); offered.clear(); looked.clear(); // BH-S7: a loaded world starts fresh (OB-126)
      const b = getBook(); if (!b) return 0;
      let added = 0;
      for (let i = 1; i < b.count; i++) {
        const g = b.def(i).giver; if (!g) continue;
        for (const id of [g.npc, g.turnIn]) {
          if (!id) continue;
          const h = w.get(id), d = h && h.data, c = d && d.components;
          if (!c || !d.transform) continue;
          if (c.waystone && c.waystone.kind === 'relay') { relayEnt.set(c.waystone.id, id); continue; } // relay: its own relay.wake touch -> onEvent
          if (c.dialogue) continue;
          const key = 'qi.' + id;
          if (w.interactables.some((r) => r.key === key)) continue;
          w.addInteractable({ key, name: 'quest.inspect', x: d.transform.x, y: d.transform.y, z: d.transform.z + 0.6, pick: (w.propPickBox && w.propPickBox(PICK_PROP[id] || id)) || undefined, pickShapes: (w.propPickShapes && w.propPickShapes(PICK_PROP[id] || id)) || undefined, radius: 2.4, prompt: promptFor('Inspect', labelOf(id)), def: { objectId: id } });
          added++;
        }
      }
      added += api.loadTexts(w);
      return added;
    },
    /** gameHooks event: touching an awake relay inspects its errands. */
    onEvent(name, d) {
      if (name === 'prop:touched' && d && d.kind === 'relay') {
        const id = relayEnt.get(d.id); if (!id) return;
        // OB-126: the FIRST touch of a relay that has an errand to give only OFFERS it (banner + the blue '!'); a later touch accepts. Nothing enters the journal unasked.
        const b = getBook();
        if (b && !offered.has(id)) for (let i = 1; i < b.count; i++) {
          const df = b.def(i);
          if (df.giver && df.giver.npc === id && b.status(i) === 1) { // 1 = AVAILABLE
            offered.add(id);
            if (note) note(df.title || id, (df.lines && df.lines.offer) || (df.giver.text ? [df.giver.text] : []));
            return;
          }
        }
        api.inspected(id);
      }
    },
    /** Any inspect of entity `id`: sets talk.<site> while an errand wants it, then lets the book act. */
    inspected(id) {
      const f = 'talk.' + siteOf(id);
      if (wants(f)) questFlag(f, true);
      if (id === 'cellarNote') questFlag('under.fordCellar.noteRead', true); // UNDER-03: smugglers tally in the Ford cellar
      if (id === 'fordMark') questFlag('lore.fordMark.read', true); // mq.smoke: the mark cut in the Ford Relay base
      if (id === 'owBoard') questFlag('lore.owBoard.read', true); // mq.ow.board (Ch3)
      if (id === 'pierStone') questFlag('lore.pierStone.read', true); // sq.hw.piers (QL-21)
      if (id === 'knot' || id === 'relayKnot') questFlag('lore.knot.read', true); // mq.bend.call: inspect prop on the relay mount
      const t = T[textOf.get(id) || Object.keys(T).find((k) => (T[k].entities || []).includes(id)) || (id === 'relayKnot' ? 'note.knot' : '')];
      if (t && note) { // banner only, never locks; 2nd+ look shows the `again` variant, the gate keeps its locked hint
        const ag = looked.has(id) && t.again && T[t.again];
        note((ag || t).title || t.title, (ag || t).lines);
        if (t.hint) note(t.hintTitle || t.title, [t.hint]);
        looked.add(id);
      }
      if (id === 'sealedGate') return; // requireItem gate.key: never satisfied yet (Part II): no book action
      const res = inspect(id);
      if (!res && note && !t) { // OB-133: a giver object with nothing to do now (not yet open / already done) still answers E with a line
        const b = getBook(); let giver = false, done = false;
        if (b) for (let i = 1; i < b.count; i++) { const g = b.def(i).giver; if (g && (g.npc === id || g.turnIn === id)) { giver = true; if (b.status(i) === 4) done = true; } }
        if (giver) { const nm = labelOf(id); note(nm.charAt(0).toUpperCase() + nm.slice(1), [done ? 'Nothing more to do here.' : 'Nothing to do with it yet.']); }
      }
    },
    /** dialogueCtl.onTalk(npcId): talk flag only (the dialogue itself drives accept / hand-in). */
    talked(id) { api.mainSync(0); const f = 'talk.' + siteOf(id); if (wants(f)) questFlag(f, true); api.mainSync(0); }, // 1st sync applies the dialogue's accept flag (Hesk: accept + talk in one conversation)
    /** combat:hit {target}: any target whose `<id>.hit` flag is an objective of an ACTIVE quest (sq.straw target1-3, sq.ow.range owTarget1-3, ...). */
    hit(p) {
      const t = p && typeof p.target === 'string' ? p.target : null;
      if (t && wants(t + '.hit')) questFlag(t + '.hit', true);
    },
    /**
     * Rook's main quests: publish book status as world.state flags, consume the dialogue's accept / handin flags,
     * set relay.bend.pulseSeen (PULSE_DELAY s after the Bend relay wakes; dt = seconds since the last call) and the Ford
     * relay's glass flag (mq.ford.mirror.glass) while relay.mirror is in the pack. Returns true when something changed.
     */
    mainSync(dt = 0) {
      const b = getBook(); if (!b || !world || !world.state) return false;
      const st = world.state; let ch = false;
      const put = (k, v) => { if (!!st[k] !== v) { if (v) st[k] = true; else delete st[k]; ch = true; } };
      if (st['waystone.ws_roadBend.woken'] && !st['relay.bend.pulseSeen']) {
        pulseT = pulseT < 0 ? 0 : pulseT + dt;
        if (pulseT >= PULSE_DELAY) { questFlag('relay.bend.pulseSeen', true); ch = true; }
      }
      if (nestWaiting.length && api.itemTaken(T[textOf.get(nestWaiting[0])].afterItem)) { for (const id of nestWaiting) { const h = world.get(id); if (h && h.data) api.addLook(world, id, h.data); } nestWaiting = []; ch = true; }
      for (const cp of CHART_PIECES) put(cp, !!(b.packOps && b.packOps.count(cp) > 0)); // MAP-28: a chart piece in the pack = world flag chart.<area>
      put('mq.ford.mirror.glass', !!(b.packOps && b.packOps.count('relay.mirror') > 0));
      for (const id of MQ) {
        const k = 'mq.' + id.slice(3) + '.';
        if (st[k + 'accept']) { if (b.statusOf(id) !== 1 || b.accept(id)) { delete st[k + 'accept']; ch = true; } }
        if (st[k + 'handin']) { if (b.statusOf(id) !== 3 || b.handIn(id)) { delete st[k + 'handin']; ch = true; } }
        const s = b.statusOf(id);
        put(k + 'available', s === 1); put(k + 'active', s === 2 || s === 3); put(k + 'ready', s === 3); put(k + 'done', s === 4);
      }
      return ch;
    },
    /** ~1 Hz: Burl within ESCORT_R of the Bend relay while sq.burl.walk is active (he needs a walk path to get there: content). */
    escortTick() {
      api.mainSync(1.067); // ~64 frames at 60 Hz
      if (!world || status('sq.burl.walk') !== ACTIVE) return false;
      const b = world.get('bear'), r = world.get('relayBend'), bt = b && b.data && b.data.transform, rt = r && r.data && r.data.transform;
      if (!bt || !rt) return false;
      if (b.data.components && b.data.components.walks && b.data.components.walks.toBend) return false; // M4: burlEscort leads him there and fires the flag on arrival
      const dx = bt.x - rt.x, dy = bt.y - rt.y;
      if (dx * dx + dy * dy > ESCORT_R * ESCORT_R) return false;
      questFlag('escort.bear.relayBend', true); return true;
    },
  };
  return api;
}
